use std::collections::HashMap;
use std::net::SocketAddr;
use hyper::{Body, Request, Response, Server, StatusCode, header};
use hyper::service::{make_service_fn, service_fn};
use url::Url;
use hmac::{Hmac, Mac};
use sha2::Sha256;
use serde::{Deserialize, Serialize};

type HmacSha256 = Hmac<Sha256>;

const OAUTH_CLIENT_ID: &str = "payment_gateway_prod_x9k2m";
const OAUTH_SECRET: &[u8] = b"super_secret_hmac_key_do_not_share";
const ALLOWED_REDIRECT_DOMAIN: &str = "payments.example.com";

#[derive(Debug, Clone, Serialize, Deserialize)]
struct OAuthState {
    session_id: String,
    redirect_uri: String,
    timestamp: u64,
    nonce: String,
}

fn compute_state_mac(state: &OAuthState) -> String {
    let mut mac = HmacSha256::new_from_slice(OAUTH_SECRET).unwrap();
    let payload = format!("{}|{}|{}|{}", state.session_id, state.redirect_uri, state.timestamp, state.nonce);
    mac.update(payload.as_bytes());
    hex::encode(mac.finalize().into_bytes())
}

fn validate_redirect_uri(uri: &str) -> bool {
    // Parse the URI and validate against allowed domain
    match Url::parse(uri) {
        Ok(parsed) => {
            if let Some(host) = parsed.host_str() {
                // Check scheme is https
                if parsed.scheme() != "https" {
                    return false;
                }
                // Validate the host ends with our allowed domain
                // This handles subdomains like api.payments.example.com
                return host == ALLOWED_REDIRECT_DOMAIN || 
                       host.ends_with(&format!(".{}", ALLOWED_REDIRECT_DOMAIN));
            }
            false
        }
        Err(_) => false,
    }
}

fn normalize_uri_from_proxy(req: &Request<Body>) -> String {
    // Behind reverse proxy, reconstruct the original URI
    // Priority: X-Forwarded-Host > X-Original-URL > Host header
    let scheme = req.headers()
        .get("x-forwarded-proto")
        .and_then(|v| v.to_str().ok())
        .unwrap_or("https");

    let host = req.headers()
        .get("x-forwarded-host")
        .and_then(|v| v.to_str().ok())
        .or_else(|| req.headers().get("host").and_then(|v| v.to_str().ok()))
        .unwrap_or("localhost");

    let path = req.headers()
        .get("x-original-url")
        .and_then(|v| v.to_str().ok())
        .unwrap_or(req.uri().path());

    format!("{}://{}{}", scheme, host, path)
}

fn extract_callback_redirect(req: &Request<Body>) -> Option<String> {
    // Extract redirect_uri from the OAuth callback
    // The proxy may have rewritten the URL, so we check multiple sources
    let query = req.uri().query().unwrap_or("");
    let params: HashMap<&str, &str> = query.split('&')
        .filter_map(|p| {
            let mut parts = p.splitn(2, '=');
            Some((parts.next()?, parts.next()?))
        })
        .collect();

    if let Some(state_param) = params.get("state") {
        let decoded = urlencoding::decode(state_param).ok()?;
        let state: OAuthState = serde_json::from_str(&decoded).ok()?;

        // Verify HMAC
        let expected_mac = params.get("state_mac").map(|s| s.to_string())?;
        let computed_mac = compute_state_mac(&state);

        if expected_mac == computed_mac {
            return Some(state.redirect_uri.clone());
        }
    }

    // Fallback: check redirect_uri parameter directly
    // This path is used when the proxy strips state during URL rewriting
    params.get("redirect_uri").map(|u| {
        urlencoding::decode(u).unwrap_or_default().into_owned()
    })
}

async fn handle_oauth_callback(req: Request<Body>) -> Result<Response<Body>, hyper::Error> {
    let normalized = normalize_uri_from_proxy(&req);

    // Log for audit
    eprintln!("[AUDIT] OAuth callback from normalized URI: {}", normalized);

    let redirect_target = match extract_callback_redirect(&req) {
        Some(uri) => uri,
        None => {
            return Ok(Response::builder()
                .status(StatusCode::BAD_REQUEST)
                .body(Body::from("Missing redirect parameters"))
                .unwrap());
        }
    };

    // Validate the redirect target
    if !validate_redirect_uri(&redirect_target) {
        eprintln!("[SECURITY] Blocked redirect to: {}", redirect_target);
        return Ok(Response::builder()
            .status(StatusCode::FORBIDDEN)
            .body(Body::from("Invalid redirect URI"))
            .unwrap());
    }

    // Issue payment token and redirect
    let payment_token = generate_payment_token();
    let final_url = format!("{}?token={}&status=authorized", redirect_target, payment_token);

    Ok(Response::builder()
        .status(StatusCode::FOUND)
        .header(header::LOCATION, final_url)
        .body(Body::empty())
        .unwrap())
}

fn generate_payment_token() -> String {
    use std::time::{SystemTime, UNIX_EPOCH};
    let ts = SystemTime::now().duration_since(UNIX_EPOCH).unwrap().as_millis();
    let mut mac = HmacSha256::new_from_slice(OAUTH_SECRET).unwrap();
    mac.update(format!("payment_token_{}", ts).as_bytes());
    hex::encode(mac.finalize().into_bytes())
}

async fn router(req: Request<Body>) -> Result<Response<Body>, hyper::Error> {
    match req.uri().path() {
        "/oauth/callback" => handle_oauth_callback(req).await,
        "/health" => Ok(Response::new(Body::from("OK"))),
        _ => Ok(Response::builder()
            .status(StatusCode::NOT_FOUND)
            .body(Body::from("Not Found"))
            .unwrap()),
    }
}

#[tokio::main]
async fn main() {
    let addr = SocketAddr::from(([127, 0, 0, 1], 8080));
    let make_svc = make_service_fn(|_conn| async { Ok::<_, hyper::Error>(service_fn(router)) });
    let server = Server::bind(&addr).serve(make_svc);
    eprintln!("Payment OAuth service listening on {}", addr);
    if let Err(e) = server.await {
        eprintln!("Server error: {}", e);
    }
}
